import{_ as a,c as n,a as t,o as e}from"./app-5valQcRL.js";const p="/blog-vp-reco/DeepLearning/Activation/04_relu6.png",l="/blog-vp-reco/DeepLearning/Activation/05_hswish.png",m={};function i(o,s){return e(),n("div",null,[...s[0]||(s[0]=[t('<h2 id="_1-前置知识-relu6" tabindex="-1"><a class="header-anchor" href="#_1-前置知识-relu6"><span>1. 前置知识：ReLU6</span></a></h2><p>2017 年，Google 在设计 MobileNetV2 时遇到一个问题：ReLU 没有上界，输入很大时输出也很大，在手机的低精度计算（INT8）中容易溢出。</p><p>解决办法很简单：给 ReLU 加一个上界 6，变成 <strong>ReLU6</strong>。</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>ReLU6</mtext><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>=</mo><mi>min</mi><mo>⁡</mo><mo stretchy="false">(</mo><mi>max</mi><mo>⁡</mo><mo stretchy="false">(</mo><mn>0</mn><mo separator="true">,</mo><mi>x</mi><mo stretchy="false">)</mo><mo separator="true">,</mo><mn>6</mn><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\text{ReLU6}(x) = \\min(\\max(0, x), 6) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">ReLU6</span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">min</span><span class="mopen">(</span><span class="mop">max</span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">6</span><span class="mclose">)</span></span></span></span></span></p><figure><img src="'+p+`" alt="1. ReLU6 激活函数图像" width="560" tabindex="0" loading="lazy"><figcaption>1. ReLU6 激活函数图像</figcaption></figure><p><strong>ReLU 家族：</strong></p><table><thead><tr><th>名称</th><th>公式</th><th>上界</th><th>说明</th></tr></thead><tbody><tr><td>ReLU</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>max</mi><mo>⁡</mo><mo stretchy="false">(</mo><mn>0</mn><mo separator="true">,</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\max(0, x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">max</span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span></td><td>无</td><td>原版</td></tr><tr><td>ReLU6</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>min</mi><mo>⁡</mo><mo stretchy="false">(</mo><mi>max</mi><mo>⁡</mo><mo stretchy="false">(</mo><mn>0</mn><mo separator="true">,</mo><mi>x</mi><mo stretchy="false">)</mo><mo separator="true">,</mo><mn>6</mn><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\min(\\max(0, x), 6)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">min</span><span class="mopen">(</span><span class="mop">max</span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">6</span><span class="mclose">)</span></span></span></span></td><td>6</td><td>MobileNet 用</td></tr><tr><td>ReLU1/2/3/4/5</td><td>...</td><td>1/2/3/4/5</td><td>几乎没人用</td></tr></tbody></table><p>ReLU1 到 ReLU5 都有人试过，但只有 ReLU6 被广泛采用。6 是一个经验选择的值：足够大（不会截断太多特征），又足够小（适合低精度计算）。</p><p><strong>PyTorch 中的使用：</strong></p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token comment"># ReLU6 激活函数</span></span>
<span class="line"><span class="token keyword">import</span> torch<span class="token punctuation">.</span>nn <span class="token keyword">as</span> nn</span>
<span class="line">relu6 <span class="token operator">=</span> nn<span class="token punctuation">.</span>ReLU6<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或者用函数式接口</span></span>
<span class="line"><span class="token keyword">import</span> torch<span class="token punctuation">.</span>functional <span class="token keyword">as</span> F</span>
<span class="line">output <span class="token operator">=</span> F<span class="token punctuation">.</span>relu6<span class="token punctuation">(</span><span class="token builtin">input</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_2-数学原理-用-relu6-近似-sigmoid" tabindex="-1"><a class="header-anchor" href="#_2-数学原理-用-relu6-近似-sigmoid"><span>2. 数学原理：用 ReLU6 近似 Sigmoid</span></a></h2><p>2019 年，Google 在设计 MobileNetV3 时，想在移动端用 Swish（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo>⋅</mo><mi>σ</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">x \\cdot \\sigma(x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">σ</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span>），但 Sigmoid 计算量太大。</p><p>他们的办法是：<strong>用 ReLU6 代替 Sigmoid</strong>。</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>h-swish</mtext><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>=</mo><mi>x</mi><mo>⋅</mo><mfrac><mrow><mtext>ReLU6</mtext><mo stretchy="false">(</mo><mi>x</mi><mo>+</mo><mn>3</mn><mo stretchy="false">)</mo></mrow><mn>6</mn></mfrac></mrow><annotation encoding="application/x-tex">\\text{h-swish}(x) = x \\cdot \\frac{\\text{ReLU6}(x+3)}{6} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">h-swish</span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.113em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">6</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">ReLU6</span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">3</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><figure><img src="`+l+`" alt="2. h-swish 激活函数图像" width="560" tabindex="0" loading="lazy"><figcaption>2. h-swish 激活函数图像</figcaption></figure><p><strong>为什么能代替？</strong>，看图其实就已经知道了，ReLU6(x+3)/6 的曲线和 Sigmoid(x) 的曲线形状很像：</p><table><thead><tr><th>x</th><th>Sigmoid(x)</th><th>ReLU6(x+3)/6</th></tr></thead><tbody><tr><td>-5</td><td>0.007</td><td>0</td></tr><tr><td>0</td><td>0.5</td><td>0.5</td></tr><tr><td>5</td><td>0.993</td><td>1</td></tr></tbody></table><p>在 x 很大或很小时，两者几乎一致；中间区域是分段线性近似。</p><h2 id="_3-swish-vs-h-swish" tabindex="-1"><a class="header-anchor" href="#_3-swish-vs-h-swish"><span>3. Swish vs h-swish</span></a></h2><table><thead><tr><th>特性</th><th>Swish</th><th>h-swish</th></tr></thead><tbody><tr><td>公式</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo>⋅</mo><mi>σ</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">x \\cdot \\sigma(x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">σ</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span></td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo>⋅</mo><mtext>ReLU6</mtext><mo stretchy="false">(</mo><mi>x</mi><mo>+</mo><mn>3</mn><mo stretchy="false">)</mo><mi mathvariant="normal">/</mi><mn>6</mn></mrow><annotation encoding="application/x-tex">x \\cdot \\text{ReLU6}(x+3) / 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">ReLU6</span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">3</span><span class="mclose">)</span><span class="mord">/6</span></span></span></span></td></tr><tr><td>计算量</td><td>大（需要 Sigmoid）</td><td>小（只有 ReLU6）</td></tr><tr><td>精度</td><td>高</td><td>接近 Swish</td></tr><tr><td>移动端</td><td>不友好</td><td>友好</td></tr></tbody></table><h2 id="_4-pytorch-中的使用" tabindex="-1"><a class="header-anchor" href="#_4-pytorch-中的使用"><span>4. PyTorch 中的使用</span></a></h2><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token comment"># h-swish 激活函数</span></span>
<span class="line"><span class="token keyword">import</span> torch<span class="token punctuation">.</span>nn <span class="token keyword">as</span> nn</span>
<span class="line">h_swish <span class="token operator">=</span> nn<span class="token punctuation">.</span>Hardswish<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或者手动实现</span></span>
<span class="line"><span class="token keyword">import</span> torch<span class="token punctuation">.</span>nn<span class="token punctuation">.</span>functional <span class="token keyword">as</span> F</span>
<span class="line"><span class="token keyword">def</span> <span class="token function">h_swish</span><span class="token punctuation">(</span>x<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">return</span> x <span class="token operator">*</span> F<span class="token punctuation">.</span>relu6<span class="token punctuation">(</span>x <span class="token operator">+</span> <span class="token number">3</span><span class="token punctuation">)</span> <span class="token operator">/</span> <span class="token number">6</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_5-应用场景-什么时候用-h-swish" tabindex="-1"><a class="header-anchor" href="#_5-应用场景-什么时候用-h-swish"><span>5. 应用场景：什么时候用 h-swish？</span></a></h2><p><strong>手机端追求精度时用 h-swish：</strong></p><table><thead><tr><th>场景</th><th>为什么用 h-swish</th><th>例子</th></tr></thead><tbody><tr><td>MobileNetV3</td><td>深层用 h-swish，精度更高</td><td>手机图像分类</td></tr><tr><td>移动端目标检测</td><td>平衡精度和速度</td><td>手机端 SSD</td></tr><tr><td>边缘设备</td><td>计算量小，适合 NPU</td><td>智能摄像头</td></tr></tbody></table><p><strong>h-swish 的分层策略（精度与速度的平衡）：</strong></p><p>MobileNetV3 的做法是：浅层用 ReLU，深层用 h-swish。</p><table><thead><tr><th>层</th><th>特征图大小</th><th>激活函数</th><th>原因</th></tr></thead><tbody><tr><td>浅层</td><td>大（112×112）</td><td>ReLU</td><td>计算量小</td></tr><tr><td>深层</td><td>小（7×7）</td><td>h-swish</td><td>精度高，计算量可接受</td></tr></tbody></table><p>这是因为浅层的特征图大，计算量主要在空间维度；深层的特征图小，计算量主要在通道维度，h-swish 的额外开销可以接受。</p><blockquote><p>h-swish 是移动端的 Swish 替代品，用 <code>nn.Hardswish()</code>。</p></blockquote>`,30)])])}const r=a(m,[["render",i]]),h=JSON.parse('{"path":"/blogs/DeepLearning/ActivationFunction/05_HardSwish.html","title":"HardSwish 激活函数","lang":"en-US","frontmatter":{"title":"HardSwish 激活函数","date":"2026/05/30","categories":["激活函数"],"tags":["激活函数","HardSwish","h-swish","ReLU6"]},"headers":[{"level":2,"title":"1. 前置知识：ReLU6","slug":"_1-前置知识-relu6","link":"#_1-前置知识-relu6","children":[]},{"level":2,"title":"2. 数学原理：用 ReLU6 近似 Sigmoid","slug":"_2-数学原理-用-relu6-近似-sigmoid","link":"#_2-数学原理-用-relu6-近似-sigmoid","children":[]},{"level":2,"title":"3. Swish vs h-swish","slug":"_3-swish-vs-h-swish","link":"#_3-swish-vs-h-swish","children":[]},{"level":2,"title":"4. PyTorch 中的使用","slug":"_4-pytorch-中的使用","link":"#_4-pytorch-中的使用","children":[]},{"level":2,"title":"5. 应用场景：什么时候用 h-swish？","slug":"_5-应用场景-什么时候用-h-swish","link":"#_5-应用场景-什么时候用-h-swish","children":[]}],"git":{"createdTime":1780239520000,"updatedTime":1780239520000,"contributors":[{"name":"jinkai","email":"1213860588@qq.com","commits":1}]},"filePathRelative":"blogs/DeepLearning/ActivationFunction/05_HardSwish.md"}');export{r as comp,h as data};
